import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.nio.ByteBuffer;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;

public class SessionManager {
    private final byte[] masterSecret;
    private final ConcurrentHashMap<String, Long> sessions = new ConcurrentHashMap<>();
    private final SecureRandom csprng;

    public SessionManager() throws Exception {
        this.csprng = SecureRandom.getInstanceStrong();
        this.masterSecret = new byte[32];
        csprng.nextBytes(masterSecret);
    }

    /**
     * Derives a per-session key from the master secret using
     * a domain separation approach with session-specific salt.
     */
    private byte[] deriveSessionKey(String userId, long sessionId) throws Exception {
        byte[] salt = new byte[32];
        csprng.nextBytes(salt);

        // Mix salt with master secret using HMAC-based extraction
        Mac extractor = Mac.getInstance("HmacSHA256");
        SecretKeySpec extractKey = new SecretKeySpec(salt, "HmacSHA256");
        extractor.init(extractKey);
        extractor.update(masterSecret);
        extractor.update(ByteBuffer.allocate(8).putLong(sessionId).array());
        extractor.update(userId.getBytes("UTF-8"));
        return extractor.doFinal();
    }

    public String createSession(String userId) throws Exception {
        long sessionId = csprng.nextLong();
        byte[] sessionKey = deriveSessionKey(userId, sessionId);

        // Generate session token using HMAC
        Mac hmac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(sessionKey, "HmacSHA256");
        hmac.init(keySpec);

        ByteBuffer payload = ByteBuffer.allocate(8 + userId.getBytes("UTF-8").length);
        payload.putLong(sessionId);
        payload.put(userId.getBytes("UTF-8"));

        byte[] mac = hmac.doFinal(payload.array());
        String token = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(ByteBuffer.allocate(8 + mac.length)
                .putLong(sessionId).put(mac).array());

        sessions.put(token, System.currentTimeMillis());
        return token;
    }

    public boolean validateSession(String token) {
        Long created = sessions.get(token);
        if (created == null) return false;
        // 24-hour expiry
        return (System.currentTimeMillis() - created) < 86400000L;
    }

    /**
     * Generates a CSRF token bound to the session.
     * Uses the session key derivation to ensure binding.
     */
    public String generateCsrfToken(String userId, String sessionToken) throws Exception {
        if (!validateSession(sessionToken)) {
            throw new SecurityException("Invalid session");
        }
        long nonce = csprng.nextLong();
        byte[] csrfKey = deriveSessionKey(userId, nonce);

        Mac hmac = Mac.getInstance("HmacSHA256");
        SecretKeySpec keySpec = new SecretKeySpec(csrfKey, "HmacSHA256");
        hmac.init(keySpec);

        byte[] csrfMac = hmac.doFinal(sessionToken.getBytes("UTF-8"));
        return Base64.getUrlEncoder().withoutPadding().encodeToString(csrfMac);
    }
}
